    private const string LOCAL_UPDATE_FILE = "C:\\AutoUpdater\\update.exe";

    // Define the service constructor and other methods
    public AutoUpdaterService()
    {
        // Create the service control manager
        ServiceControlManager scm = new ServiceControlManager();

        // Register the service with the service control manager
        scm.RegisterService(this);

        // Start the service
